-- Flame Chick public media bucket and role-restricted management.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('flame-chick-media','flame-chick-media',true,5242880,array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy flame_chick_media_public_read on storage.objects for select to public using (bucket_id='flame-chick-media');
create policy flame_chick_media_staff_insert on storage.objects for insert to authenticated with check (bucket_id='flame-chick-media' and (storage.foldername(name))[1]=any(array['products','categories','deals','site','menu-slides']::text[]) and private.has_staff_role(null::uuid,array['owner','admin','manager']::text[]));
create policy flame_chick_media_staff_update on storage.objects for update to authenticated using (bucket_id='flame-chick-media' and (storage.foldername(name))[1]=any(array['products','categories','deals','site','menu-slides']::text[]) and private.has_staff_role(null::uuid,array['owner','admin','manager']::text[])) with check (bucket_id='flame-chick-media' and (storage.foldername(name))[1]=any(array['products','categories','deals','site','menu-slides']::text[]) and private.has_staff_role(null::uuid,array['owner','admin','manager']::text[]));
create policy flame_chick_media_staff_delete on storage.objects for delete to authenticated using (bucket_id='flame-chick-media' and (storage.foldername(name))[1]=any(array['products','categories','deals','site','menu-slides']::text[]) and private.has_staff_role(null::uuid,array['owner','admin','manager']::text[]));
